async function startDeduction(s,payload={}){let r=await act(s[0],'start',{difficulty:'classic',rounds:3,...payload});assert.equal(r.phase,'deducing');await editRoom(s[0],room=>{room.deductionStarts=Date.now()/1000-5;});return act(s[0],'state');}
const ruleData=JSON.parse((await readFile('api/rulebreakers-data.php','utf8')).split("<<<'RULES'\n")[1].split('\nRULES')[0]);
function ruleTruth(rule,word){const i=ruleData.words.indexOf(word),a=ruleData.atoms.find(a=>a.id===rule.a),b=ruleData.atoms.find(a=>a.id===rule.b);const bit=atom=>!!(Buffer.from(atom.mask,'base64')[i>>3]&(1<<(i%8)));return rule.op==='single'?bit(a):rule.op==='and'?bit(a)&&bit(b):rule.op==='or'?bit(a)||bit(b):rule.op==='xor'?bit(a)!==bit(b):bit(a)&&!bit(b);}
test('Rulebreakers validates dictionary probes, keeps hypotheses private and accepts equivalent composed rules',async()=>{
 const s=await create('rulebreakers',2);let r=await startDeduction(s);const stored=await storedDeduction(s[0]),rule=stored.deductionPuzzle.rule;assert.equal(r.atoms.length,244);assert.ok(!('solution'in r));assert.ok(!('puzzleKey'in r));assert.ok(!JSON.stringify(r).includes('"mask"'));for(const w of r.examples.yes)assert.equal(ruleTruth(rule,w),true);for(const w of r.examples.no)assert.equal(ruleTruth(rule,w),false);
 await act(s[0],'probe',{word:'zzzzzz'},400);const example=[...r.examples.yes,...r.examples.no];const word=ruleData.words.find(w=>!example.includes(w));r=await act(s[0],'probe',{word});assert.equal(r.state.probes[0].pass,ruleTruth(rule,word));await act(s[0],'probe',{word},409);assert.deepEqual((await act(s[1],'state')).state.probes,[]);
 r=await act(s[0],'rule',{a:'a0',op:'single',b:null});assert.equal(r.state.wrong,1);const counter=r.state.guesses[0].counter;assert.equal(counter.pass,ruleTruth(rule,counter.word));await act(s[0],'rule',{a:'bogus',op:'single'},400);assert.equal((await act(s[1],'state')).state.wrong,0);
 r=await act(s[0],'rule',{a:rule.b,op:rule.op,b:rule.a});assert.equal(r.state.solved,true);assert.equal(r.phase,'deducing');await act(s[0],'probe',{word:'house'},409);r=await act(s[1],'rule',rule);assert.equal(r.phase,'reveal');assert.equal(r.result.scores[s[0].id],10);assert.equal(r.result.scores[s[1].id],12);assert.equal(r.solution.rule.id,rule.id);const score=r.players.map(p=>p.score);assert.deepEqual((await act(s[0],'state')).players.map(p=>p.score),score);
});
