test('all new deduction games complete three rounds, restart and avoid recent rules or case setups',async()=>{
 for(const game of ['rulebreakers','alien-dictionary','question-quest']){const s=await create(game,2);let r=await startDeduction(s);const used=new Set();for(let round=1;round<=3;round++){assert.equal(r.round,round);await act(s[0],'end_race');r=await act(s[0],'state');if(game!=='alien-dictionary'){assert.ok(!used.has(r.puzzleKey));used.add(r.puzzleKey);}r=await act(s[0],'next');if(round<3){assert.equal(r.phase,'deducing');await editRoom(s[0],room=>{room.deductionStarts=Date.now()/1000-5;});}}assert.equal(r.phase,'finished');r=await act(s[0],'again',{rounds:1,recent:[...used]});const stored=await storedDeduction(s[0]);if(game==='rulebreakers')assert.ok(!used.has(stored.deductionPuzzle.rule.id));if(game==='question-quest')assert.ok(!used.has(stored.deductionPuzzle.story.key));assert.equal(r.round,1);}
});

const jbGames=['quiz-after-dark','punchline','fact-or-fiction','doodle-bluff','last-laugh-trivia','thread-battle'];
const strokes=[{color:'#292039',width:4,points:[[10,10],[200,90],[350,250]]}];
async function stored(session){return JSON.parse(await readFile(path.join(dataRoot,session.code+'.json'),'utf8'));}
async function changeStored(session,fn){const r=await stored(session);fn(r);await writeFile(path.join(dataRoot,session.code+'.json'),JSON.stringify(r));}
async function voteAll(s){let last;for(const player of s){const view=await act(player,'state');if(view.phase!=='jb-voting')continue;for(const e of view.entries){if(e.eligible.length&&e.yourVote===null)last=await act(player,'vote',{entry:e.id,choice:e.eligible[0]});}}return last||await act(s[0],'state');}
async function completeJb(s){
 let r=await act(s[0],'state');
 if(r.phase==='jb-trivia'){const secret=await stored(s[0]);for(const player of s){r=await act(player,'answer',{choice:secret.jbQuestion.correct});}return r;}
 if(r.phase==='jb-drawing'){for(const player of s)r=await act(player,'draw',{strokes});}
 if(r.phase==='jb-writing'){
  for(const [i,player] of s.entries()){const v=await act(player,'state');r=await act(player,'write',v.prompts?{answers:Object.fromEntries(v.prompts.map(p=>[p.id,`Funny ${i} response ${p.id}`]))}:{text:`a suspicious ${i} toaster`});}
 }
 if(r.phase==='jb-bluffing'){for(const [i,player] of s.entries()){const v=await act(player,'state');for(const pic of v.pictures)r=await act(player,'bluff',{picture:pic.id,text:`a fake label ${i} for ${pic.id}`});}}
 if(r.phase==='jb-slogans')for(const [i,player] of s.entries())r=await act(player,'slogans',{texts:[`Slogan ${i} A`,`Slogan ${i} B`]});
 if(r.phase==='jb-designing')for(const [i,player] of s.entries()){const v=await act(player,'state');r=await act(player,'design',{drawing:v.artworks[i%v.artworks.length].id,slogan:v.slogans[i%v.slogans.length].id});}
 return voteAll(s);
}
test('one party joins from any game, retains identities and code across every game, and rejects stale actions',async()=>{
 const s=await create('party',2);const first=await act(s[0],'state');await act(s[1],'select_game',{selection:'imposter'},403);await act(s[0],'select_game',{selection:'invalid-game'},400);
 const cross=(await api('join',{}, {game:'sudoku-race',code:s[0].code,name:'Cross-game friend'})).session;s.push(cross);
 for(const game of ['wavelength','imposter','scattergories','hivemind','apples','humanity','desktop-disaster','word-circuit','sudoku-race','rulebreakers','alien-dictionary','question-quest',...jbGames,'barcraft','party']){
  const previous=await act(s[0],'state');const r=await act(s[0],'select_game',{selection:game});assert.equal(r.code,first.code);assert.equal(r.host,first.host);assert.deepEqual(r.players.map(p=>p.id),s.map(p=>p.id));assert.equal(r.game,game);assert.equal(r.phase,'lobby');assert.equal(r.gameEpoch,previous.gameEpoch+1);assert.equal('target' in r,false);assert.equal('word' in r,false);assert.equal('entries' in r,false);await act(s[0],'start',{gameEpoch:previous.gameEpoch},409);for(const p of s)p.game=game;
 }
 await act(s[1],'leave');const r=await act(s[0],'state');assert.equal(r.players.length,2);
});
test('all six Jackbox adaptations complete full three-round sessions, restart, and support two-player mode',async()=>{
 for(const game of jbGames)for(const count of [2,4]){const s=await create(game,count);let r=await act(s[0],'start',{rounds:3});for(let n=1;n<=3;n++){assert.equal(r.round,n,game);r=await completeJb(s);assert.equal(r.phase,'reveal',game);const before=r.players.map(p=>p.score);const again=await act(s[0],'state');assert.deepEqual(again.players.map(p=>p.score),before,game);r=await act(s[0],'next');}assert.equal(r.phase,'finished',game);r=await act(s[0],'again',{rounds:1});assert.equal(r.round,1,game);assert.ok(r.players.every(p=>p.score===0),game);}
});
test('trivia answers stay private and screws enforce eight-second personal deadlines once per game',async()=>{
 const s=await create('quiz-after-dark',3);let r=await act(s[0],'start',{rounds:1});const truth=(await stored(s[0])).jbQuestion.correct;assert.equal('correct' in r.question,false);assert.equal('truth' in r,false);await act(s[1],'screw',{target:s[1].id},400);await act(s[0],'screw',{target:s[1].id});r=await act(s[1],'state');assert.ok(r.personalDeadline<r.deadline);await act(s[0],'screw',{target:s[2].id},409);await changeStored(s[0],r=>{r.jbJammed[s[1].id]=microtimePlaceholder();});
 function microtimePlaceholder(){return Date.now()/1000-1;}
 await act(s[1],'answer',{choice:truth},409);await act(s[2],'answer',{choice:truth});const other=await act(s[0],'state');assert.equal(other.yourAnswer,null);assert.equal('answers' in other,false);await changeStored(s[0],r=>{r.deadline=Date.now()/1000-1;});r=await act(s[0],'state');assert.equal(r.phase,'reveal');assert.equal(r.result.correct,truth);assert.ok(r.result.scores[s[1].id]<0);
});
test('bluffs remain private, real-answer submissions are rejected, own lies cannot receive own votes',async()=>{
 const s=await create('fact-or-fiction',3);await act(s[0],'start');const q=(await stored(s[0])).jbQuestion;await act(s[0],'write',{text:q.truth},400);await act(s[0],'write',{text:'believable invented thing'});let r=await act(s[1],'state');assert.equal(r.yourWriting,null);assert.equal(JSON.stringify(r).includes('believable invented thing'),false);await act(s[1],'write',{text:'another invented thing'});await act(s[2],'write',{text:'a third invention'});r=await act(s[0],'state');assert.equal(r.phase,'jb-voting');const own=r.entries[0].options.find(o=>o.text==='believable invented thing');assert.ok(!r.entries[0].eligible.includes(own.id));await act(s[0],'vote',{entry:'fact',choice:own.id},400);assert.equal(JSON.stringify(r.entries).includes('truth'),false);await voteAll(s);
});
test('drawings validate coordinates and colors, prompts stay private, and anonymous shirt pools do not expose creator IDs',async()=>{
 const s=await create('thread-battle',2);await act(s[0],'start');const a=await act(s[0],'state'),b=await act(s[1],'state');assert.notEqual(a.drawingPrompt,b.drawingPrompt);assert.equal('jbDrawingPrompts' in a,false);await act(s[0],'draw',{strokes:[{color:'url(evil)',width:4,points:[[10,10]]}]},400);await act(s[0],'draw',{strokes:[{color:'#292039',width:4,points:[[999,10]]}]},400);await act(s[0],'draw',{strokes});let r=await act(s[1],'draw',{strokes});assert.equal(r.phase,'jb-slogans');await act(s[0],'slogans',{texts:['A','B']});r=await act(s[1],'state');assert.deepEqual(r.yourSlogans,[]);await act(s[1],'slogans',{texts:['C','D']});r=await act(s[0],'state');assert.ok(r.artworks.every(a=>/^a\d+$/.test(a.id)));assert.ok(r.slogans.every(a=>/^s\d+$/.test(a.id)));assert.equal(JSON.stringify(r.artworks).includes(s[1].id),false);await act(s[0],'design',{drawing:'invalid',slogan:'s0'},400);await act(s[0],'design',{drawing:'a0',slogan:'s0'});r=await act(s[1],'design',{drawing:'a1',slogan:'s2'});assert.equal(r.entries[0].options.length,3);assert.equal(JSON.stringify(r.entries).includes('artist'),false);await voteAll(s);
});
test('survival trivia runs private traps, ghosts revive, memory previews disappear, and escape standings persist',async()=>{
 const s=await create('last-laugh-trivia',2);await act(s[0],'start',{rounds:3});let secret=await stored(s[0]);const wrong=(secret.jbQuestion.correct+1)%4;await act(s[0],'answer',{choice:wrong});let r=await act(s[1],'answer',{choice:secret.jbQuestion.correct});assert.equal(r.phase,'jb-danger');assert.equal('challenge' in r,false);const trapped=await act(s[0],'state');assert.ok(trapped.challenge);assert.equal('correct' in trapped.challenge,false);await changeStored(s[0],r=>{r.jbChallenges[s[0].id]={text:'Remember',preview:'1234',hideAt:Date.now()/1000-1,options:['1234','4321','1111','2222'],correct:0};});r=await act(s[0],'state');assert.equal('preview' in r.challenge,false);r=await act(s[0],'danger',{choice:1});assert.equal(r.phase,'reveal');assert.equal(r.lives[s[0].id],1);await act(s[0],'next');await changeStored(s[0],r=>{r.jbLives[s[0].id]=0;r.jbGhostWins={...r.jbGhostWins,[s[0].id]:1};});secret=await stored(s[0]);await act(s[0],'answer',{choice:secret.jbQuestion.correct});r=await act(s[1],'answer',{choice:secret.jbQuestion.correct});assert.equal(r.phase,'reveal');assert.equal(r.lives[s[0].id],1);assert.ok(r.escape[s[0].id]>=2);
});
